-- Generated by tools/osm_ingest.py on 2026-11-19.
-- Do not edit by hand. Regenerate into a new migration instead.
--
-- 976 cinemas from OpenStreetMap, via Overpass, within
-- 20km of each of the 40 cities this
-- database already covers.
--
-- Overpass rather than Nominatim, which V18 used. Nominatim is a
-- geocoder: it ranks its answers and caps them, because it exists to
-- answer "which one did you mean". Overpass is the bulk query
-- interface to the same database and returns everything tagged. V18
-- used Nominatim only because Overpass refused that network, so the
-- 130 rows were an artefact of the tool rather than a statement
-- about what OSM holds.
--
-- Names and coordinates are real. The osm_type and osm_id on every
-- row are the identity V24 added, so any of these can be checked
-- against openstreetmap.org and so that re-running the ingestion is
-- idempotent rather than a hand-merge.
--
-- 350 of these carry an address and 626
-- do not, because two thirds of OSM's cinemas have no addr:* tags at
-- all. V24 made the column nullable rather than filling the gap:
-- bulk reverse geocoding through Nominatim is against their usage
-- policy, a commercial geocoder would dress a vendor's guess from
-- coordinates up as something a mapper wrote, and composing
-- "Jaipur, Rajasthan" would be inventing data. The map answers
-- where a building is, exactly, and the API sends the distance.
--
-- City is assigned by nearest centre rather than by addr:city, which
-- only a third of these carry. So a Birkenhead cinema is tagged
-- Liverpool. For an app where people search for "Liverpool" that is
-- arguably right, but it is a simplification and this is it stated.
--
-- Screens and seats are not here. RoomSeeder converges on every boot
-- and will build rooms for every one of these on the next startup.
--
-- Licence is ODbL, so "(c) OpenStreetMap contributors" has to appear
-- wherever these are displayed, which it already does.

INSERT INTO cinema
    (name, city, state, address, currency, timezone, location,
     country, osm_type, osm_id)
SELECT v.name, v.city, v.state, v.address,
       CASE WHEN v.state IN ('England', 'Scotland') THEN 'GBP'
            ELSE 'INR' END,
       CASE WHEN v.state IN ('England', 'Scotland') THEN 'Europe/London'
            ELSE 'Asia/Kolkata' END,
       ST_SetSRID(ST_MakePoint(CAST(v.lon AS double precision),
                               CAST(v.lat AS double precision)),
                  4326)::geography,
       CASE WHEN v.state IN ('England', 'Scotland') THEN 'GB'
            ELSE 'IN' END,
       v.osm_type, v.osm_id
